"use client";
import type { RefObject } from "react";
import { ArtemisScope } from "./artemis-scope";
import View0 from "./components/navbar/variants/01-pill-groups";
import View1 from "./components/navbar/variants/02-mega-menu";
import View2 from "./components/navbar/variants/03-morph";
import View3 from "./components/navbar/variants/04-feature-morph";
import View4 from "./components/navbar/variants/05-expand";
import View5 from "./components/navbar/variants/06-simple";
const variants = {"pill-groups":View0,"mega-menu":View1,"morph":View2,"feature-morph":View3,"expand":View4,"simple":View5};
export interface ArtemisNavbarProps { className?: string; scrollContainer?: RefObject<HTMLElement | null>; variant?: "pill-groups" | "mega-menu" | "morph" | "feature-morph" | "expand" | "simple"; }
export function ArtemisNavbar({ className, scrollContainer, variant = "pill-groups" }: ArtemisNavbarProps) {const View = variants[variant];return <ArtemisScope className={`${variant === "expand" || variant === "simple" ? "art:sticky art:top-0 art:z-50" : "art:relative art:z-40"} ${className ?? ""}`}><div className="art:flex art:w-full art:min-w-0 art:flex-col art:items-center">{variant === "expand" ? <View4 scrollContainer={scrollContainer}/> : variant === "simple" ? <View5 scrollContainer={scrollContainer}/> : <View/>}</div></ArtemisScope>;}
